/**
 * Material-based quizzes. Questions are generated by the ai-service from the selected READY documents
 * (RagService.generateQuiz), stored per student, and graded here. The answer key (correctIndex,
 * explanation, source quote) never leaves this service before an attempt is submitted.
 */
import { Injectable } from '@nestjs/common';

import { ApiError, notFound } from '../common/errors';
import type { AuthUser } from '../common/request-context';
import { AccessService } from '../courses/access.service';
import type { Quiz, QuizAttempt, QuizQuestion } from '../generated/prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import { RagService } from '../rag/rag.service';

export const QUESTION_TYPES = ['multiple_choice', 'true_false'] as const;
export const DIFFICULTIES = ['easy', 'medium', 'hard'] as const;
export const QUESTION_COUNTS = [5, 10, 15] as const;

export interface SubmittedAnswer { question_id: string; selected_index: number | null }

type QuestionInput = {
  type: string; prompt: string; options: string[]; correct_index: number; explanation: string; topic: string; difficulty: string;
  source: { chunk_id: string; document_id: string; page_start?: number | null; page_end?: number | null; quote: string };
};

const str = (v: unknown, max: number): v is string => typeof v === 'string' && v.trim().length > 0 && v.length <= max;

/** Defence in depth: the ai-service result is validated again; malformed questions are dropped, never repaired. */
function validQuestion(q: any, allowedTypes: readonly string[]): q is QuestionInput {
  if (!q || typeof q !== 'object' || !allowedTypes.includes(q.type)) return false;
  if (!str(q.prompt, 4000) || !str(q.explanation, 4000) || !str(q.topic, 300)) return false;
  if (!Array.isArray(q.options) || q.options.length < 2 || q.options.length > 6 || !q.options.every((o: unknown) => str(o, 1000))) return false;
  if (new Set(q.options.map((o: string) => o.trim().toLowerCase())).size !== q.options.length) return false;
  if (q.type === 'true_false' && q.options.length !== 2) return false;
  if (!Number.isInteger(q.correct_index) || q.correct_index < 0 || q.correct_index >= q.options.length) return false;
  const s = q.source;
  return !!s && str(s.chunk_id, 191) && str(s.document_id, 191) && str(s.quote, 4000);
}

@Injectable()
export class QuizService {
  constructor(private readonly prisma: PrismaService, private readonly access: AccessService, private readonly rag: RagService) {}

  // ─── generation ───────────────────────────────────────────────────────────
  async create(
    user: AuthUser, courseId: string,
    input: { document_ids: string[]; question_count: number; question_types: string[]; difficulty: string }, requestId?: string,
  ) {
    await this.access.requireMember(user, courseId);
    const documentIds = [...new Set(input.document_ids)];
    const types = QUESTION_TYPES.filter((t) => input.question_types.includes(t));
    const body = await this.rag.generateQuiz(user, courseId, documentIds, { count: input.question_count, question_types: types, difficulty: input.difficulty }, requestId);
    const questions = (Array.isArray(body?.questions) ? body.questions : []).filter((q: unknown) => validQuestion(q, types)).slice(0, input.question_count);
    if (questions.length === 0) {
      const why = Array.isArray(body?.warnings) && body.warnings.length ? ` ${body.warnings.join(' ')}` : '';
      throw new ApiError('QUIZ_GENERATION_FAILED', `Seçilen materyallerden güvenilir soru üretilemedi.${why}`.trim(), { requested: input.question_count });
    }
    const warnings: string[] = (Array.isArray(body?.warnings) ? body.warnings : []).filter((w: unknown) => typeof w === 'string').slice(0, 10);
    if (questions.length < input.question_count) {
      warnings.push(`${input.question_count} soru istendi, kaynaklara dayanarak ${questions.length} soru üretilebildi.`);
    }
    const docs = await this.prisma.document.findMany({ where: { id: { in: documentIds } }, select: { id: true, title: true } });
    const course = await this.prisma.course.findUniqueOrThrow({ where: { id: courseId }, select: { name: true } });
    const title = `${course.name} · ${docs[0]?.title ?? 'Quiz'}${docs.length > 1 ? ` +${docs.length - 1}` : ''}`.slice(0, 200);
    const quiz = await this.prisma.$transaction(async (tx) => {
      const q = await tx.quiz.create({
        data: {
          userId: user.id, courseId, title, difficulty: input.difficulty, questionTypes: types.join(','),
          requestedCount: input.question_count, questionCount: questions.length,
          generator: typeof body?.generator === 'string' ? body.generator.slice(0, 64) : 'unknown', llmUsed: body?.llm_used === true,
          warnings: warnings.length ? JSON.stringify(warnings) : null,
          documents: { create: documentIds.map((documentId) => ({ documentId })) },
          questions: {
            create: questions.map((x: QuestionInput, i: number) => ({
              ordinal: i + 1, type: x.type, prompt: x.prompt.trim(), options: JSON.stringify(x.options.map((o) => o.trim())),
              correctIndex: x.correct_index, explanation: x.explanation.trim(), topic: x.topic.trim().slice(0, 300),
              difficulty: ['easy', 'medium', 'hard'].includes(x.difficulty) ? x.difficulty : input.difficulty,
              sourceDocumentId: x.source.document_id, sourceChunkId: x.source.chunk_id,
              sourcePageStart: Number.isInteger(x.source.page_start) ? (x.source.page_start as number) : null,
              sourcePageEnd: Number.isInteger(x.source.page_end) ? (x.source.page_end as number) : null,
              sourceQuote: x.source.quote,
            })),
          },
        },
        include: { questions: { orderBy: { ordinal: 'asc' } }, documents: true },
      });
      return q;
    });
    return this.quizDto(quiz, quiz.questions, quiz.documents.map((d) => d.documentId));
  }

  // ─── reading ──────────────────────────────────────────────────────────────
  async list(user: AuthUser, courseId?: string) {
    const quizzes = await this.prisma.quiz.findMany({
      where: { userId: user.id, ...(courseId ? { courseId } : {}), course: { memberships: { some: { userId: user.id } } } },
      orderBy: { createdAt: 'desc' }, take: 100,
      include: { attempts: { orderBy: { startedAt: 'desc' }, take: 1 } },
    });
    return quizzes.map((q) => {
      const a = q.attempts[0];
      return {
        id: q.id, course_id: q.courseId, title: q.title, question_count: q.questionCount, difficulty: q.difficulty,
        created_at: q.createdAt.toISOString(),
        latest_attempt: a ? { id: a.id, status: a.status, score_pct: a.scorePct, submitted_at: a.submittedAt?.toISOString() ?? null } : null,
      };
    });
  }

  async get(user: AuthUser, quizId: string) {
    const quiz = await this.ownedQuiz(user, quizId);
    const questions = await this.prisma.quizQuestion.findMany({ where: { quizId }, orderBy: { ordinal: 'asc' } });
    const docs = await this.prisma.quizDocument.findMany({ where: { quizId } });
    return this.quizDto(quiz, questions, docs.map((d) => d.documentId));
  }

  // ─── attempts ─────────────────────────────────────────────────────────────
  async startAttempt(user: AuthUser, quizId: string) {
    await this.ownedQuiz(user, quizId);
    const open = await this.prisma.quizAttempt.findFirst({ where: { quizId, userId: user.id, status: 'IN_PROGRESS' }, orderBy: { startedAt: 'desc' } });
    const attempt = open ?? await this.prisma.quizAttempt.create({ data: { quizId, userId: user.id } });
    return this.attemptDto(attempt, await this.savedAnswers(attempt.id));
  }

  async saveAnswers(user: AuthUser, attemptId: string, answers: SubmittedAnswer[]) {
    const attempt = await this.ownedAttempt(user, attemptId);
    if (attempt.status !== 'IN_PROGRESS') throw new ApiError('QUIZ_ALREADY_SUBMITTED', 'This attempt has already been submitted.');
    await this.storeAnswers(attempt, answers);
    return { answered: await this.prisma.quizAttemptAnswer.count({ where: { attemptId, selectedIndex: { not: null } } }) };
  }

  async submit(user: AuthUser, attemptId: string, answers?: SubmittedAnswer[]) {
    const attempt = await this.ownedAttempt(user, attemptId);
    if (attempt.status === 'SUBMITTED') return this.result(attempt); // idempotent
    const questions = await this.prisma.quizQuestion.findMany({ where: { quizId: attempt.quizId } });
    if (answers?.length) await this.storeAnswers(attempt, answers, questions);
    const saved = new Map((await this.prisma.quizAttemptAnswer.findMany({ where: { attemptId } })).map((a) => [a.questionId, a.selectedIndex]));
    const graded = questions.map((q) => {
      const sel = saved.get(q.id) ?? null;
      return { q, sel, ok: sel !== null && sel === q.correctIndex };
    });
    const correct = graded.filter((g) => g.ok).length;
    const total = questions.length;
    await this.prisma.$transaction(async (tx) => {
      // Single winner if the submit button is double-clicked: only an IN_PROGRESS row flips.
      const flip = await tx.quizAttempt.updateMany({
        where: { id: attemptId, status: 'IN_PROGRESS' },
        data: { status: 'SUBMITTED', submittedAt: new Date(), totalCount: total, correctCount: correct, scorePct: total ? Math.round((correct / total) * 100) : 0 },
      });
      if (flip.count === 0) return;
      for (const g of graded) {
        await tx.quizAttemptAnswer.upsert({
          where: { attemptId_questionId: { attemptId, questionId: g.q.id } },
          create: { attemptId, questionId: g.q.id, selectedIndex: g.sel, isCorrect: g.ok },
          update: { isCorrect: g.ok },
        });
      }
    });
    return this.result(await this.prisma.quizAttempt.findUniqueOrThrow({ where: { id: attemptId } }));
  }

  async getAttempt(user: AuthUser, attemptId: string) {
    const attempt = await this.ownedAttempt(user, attemptId);
    if (attempt.status === 'SUBMITTED') return this.result(attempt);
    const quiz = await this.get(user, attempt.quizId);
    return { ...this.attemptDto(attempt, await this.savedAnswers(attempt.id)), quiz };
  }

  async listAttempts(user: AuthUser, courseId?: string) {
    const rows = await this.prisma.quizAttempt.findMany({
      where: { userId: user.id, status: 'SUBMITTED', ...(courseId ? { quiz: { courseId } } : {}) },
      orderBy: { submittedAt: 'desc' }, take: 100, include: { quiz: { select: { title: true, courseId: true } } },
    });
    return rows.map((a) => ({
      id: a.id, quiz_id: a.quizId, quiz_title: a.quiz.title, course_id: a.quiz.courseId, status: a.status,
      score_pct: a.scorePct, correct_count: a.correctCount, total_count: a.totalCount, submitted_at: a.submittedAt?.toISOString() ?? null,
    }));
  }

  /** Analytics data contract (structured so the Analytics page needs no further processing). */
  async summary(user: AuthUser, courseId?: string) {
    const attempts = await this.prisma.quizAttempt.findMany({
      where: { userId: user.id, status: 'SUBMITTED', quiz: { course: { memberships: { some: { userId: user.id } } }, ...(courseId ? { courseId } : {}) } },
      orderBy: { submittedAt: 'asc' }, include: { quiz: { select: { courseId: true } } },
    });
    const answers = attempts.length
      ? await this.prisma.quizAttemptAnswer.findMany({ where: { attemptId: { in: attempts.map((a) => a.id) } }, include: { question: { select: { topic: true } } } })
      : [];
    const topics = new Map<string, { answered: number; correct: number }>();
    for (const a of answers) {
      const t = topics.get(a.question.topic) ?? { answered: 0, correct: 0 };
      t.answered += 1;
      if (a.isCorrect) t.correct += 1;
      topics.set(a.question.topic, t);
    }
    const scores = attempts.map((a) => a.scorePct ?? 0);
    return {
      completed_quizzes: new Set(attempts.map((a) => a.quizId)).size,
      average_score_pct: scores.length ? Math.round(scores.reduce((x, y) => x + y, 0) / scores.length) : null,
      attempts: attempts.map((a) => ({ attempt_id: a.id, quiz_id: a.quizId, course_id: a.quiz.courseId, submitted_at: a.submittedAt?.toISOString() ?? null, score_pct: a.scorePct })),
      topics: [...topics.entries()].map(([topic, t]) => ({ topic, answered: t.answered, correct: t.correct, accuracy_pct: Math.round((t.correct / t.answered) * 100) }))
        .sort((a, b) => a.accuracy_pct - b.accuracy_pct),
    };
  }

  // ─── internals ────────────────────────────────────────────────────────────
  private async ownedQuiz(user: AuthUser, quizId: string): Promise<Quiz> {
    const quiz = await this.prisma.quiz.findUnique({ where: { id: quizId } });
    if (!quiz || quiz.userId !== user.id || !(await this.access.membership(user.id, quiz.courseId))) throw notFound('Quiz');
    return quiz;
  }

  private async ownedAttempt(user: AuthUser, attemptId: string): Promise<QuizAttempt> {
    const attempt = await this.prisma.quizAttempt.findUnique({ where: { id: attemptId } });
    if (!attempt || attempt.userId !== user.id) throw notFound('Attempt');
    await this.ownedQuiz(user, attempt.quizId);
    return attempt;
  }

  private async savedAnswers(attemptId: string) {
    const rows = await this.prisma.quizAttemptAnswer.findMany({ where: { attemptId, selectedIndex: { not: null } } });
    return rows.map((a) => ({ question_id: a.questionId, selected_index: a.selectedIndex }));
  }

  private async storeAnswers(attempt: QuizAttempt, answers: SubmittedAnswer[], preloaded?: QuizQuestion[]): Promise<void> {
    const questions = preloaded ?? await this.prisma.quizQuestion.findMany({ where: { quizId: attempt.quizId } });
    const byId = new Map(questions.map((q) => [q.id, q]));
    for (const a of answers) {
      const q = byId.get(a.question_id);
      if (!q) throw new ApiError('VALIDATION_ERROR', 'Unknown question in answers.', { question_id: a.question_id });
      const n = (JSON.parse(q.options) as string[]).length;
      if (a.selected_index !== null && (!Number.isInteger(a.selected_index) || a.selected_index < 0 || a.selected_index >= n)) {
        throw new ApiError('VALIDATION_ERROR', 'Selected option is out of range.', { question_id: a.question_id });
      }
    }
    await this.prisma.$transaction(
      answers.map((a) => this.prisma.quizAttemptAnswer.upsert({
        where: { attemptId_questionId: { attemptId: attempt.id, questionId: a.question_id } },
        create: { attemptId: attempt.id, questionId: a.question_id, selectedIndex: a.selected_index },
        update: { selectedIndex: a.selected_index, answeredAt: new Date() },
      })),
    );
  }

  private attemptDto(a: QuizAttempt, answers: { question_id: string; selected_index: number | null }[]) {
    return { id: a.id, quiz_id: a.quizId, status: a.status, started_at: a.startedAt.toISOString(), answers };
  }

  private quizDto(q: Quiz, questions: QuizQuestion[], documentIds: string[]) {
    return {
      id: q.id, course_id: q.courseId, title: q.title, status: q.status, question_count: q.questionCount, requested_count: q.requestedCount,
      difficulty: q.difficulty, question_types: q.questionTypes.split(','), generator: q.generator, llm_used: q.llmUsed,
      warnings: q.warnings ? (JSON.parse(q.warnings) as string[]) : [], document_ids: documentIds, created_at: q.createdAt.toISOString(),
      // No answer key, explanation or source quote here.
      questions: questions.map((x) => ({
        id: x.id, ordinal: x.ordinal, type: x.type, prompt: x.prompt, options: JSON.parse(x.options) as string[], topic: x.topic, difficulty: x.difficulty,
      })),
    };
  }

  private async result(attempt: QuizAttempt) {
    const questions = await this.prisma.quizQuestion.findMany({ where: { quizId: attempt.quizId }, orderBy: { ordinal: 'asc' } });
    const saved = new Map((await this.prisma.quizAttemptAnswer.findMany({ where: { attemptId: attempt.id } })).map((a) => [a.questionId, a]));
    const docs = await this.prisma.document.findMany({
      where: { id: { in: [...new Set(questions.map((q) => q.sourceDocumentId))] } }, select: { id: true, title: true, deletedAt: true },
    });
    const docMap = new Map(docs.map((d) => [d.id, d]));
    return {
      id: attempt.id, quiz_id: attempt.quizId, status: attempt.status, score_pct: attempt.scorePct, correct_count: attempt.correctCount,
      total_count: attempt.totalCount, submitted_at: attempt.submittedAt?.toISOString() ?? null,
      results: questions.map((q) => {
        const a = saved.get(q.id);
        const doc = docMap.get(q.sourceDocumentId);
        const pages = q.sourcePageStart ? (q.sourcePageEnd && q.sourcePageEnd !== q.sourcePageStart ? `s.${q.sourcePageStart}–${q.sourcePageEnd}` : `s.${q.sourcePageStart}`) : null;
        return {
          question_id: q.id, ordinal: q.ordinal, type: q.type, prompt: q.prompt, options: JSON.parse(q.options) as string[],
          selected_index: a?.selectedIndex ?? null, correct_index: q.correctIndex, is_correct: a?.isCorrect ?? false,
          explanation: q.explanation, topic: q.topic,
          source: {
            document_id: q.sourceDocumentId, document_title: doc?.title ?? null, page_start: q.sourcePageStart, page_end: q.sourcePageEnd,
            quote: doc && !doc.deletedAt ? q.sourceQuote : null, label: [doc?.title, pages].filter(Boolean).join(' · ') || 'Kaynak',
          },
        };
      }),
    };
  }
}

